{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.BUILDSKILL_DB_PRODUCT_MARKETING_CONSOLIDATED AS WITH sku_map AS ( SELECT * FROM `maplemonk.Buildskill_GS_SKU_MASTER` QUALIFY ROW_NUMBER() OVER (PARTITION BY master_sku) = 1 ), marketing_consolidated AS ( SELECT LOWER(TRIM(channel)) AS channel, DATE(date) AS date, SUM(CAST(spend AS FLOAT64)) AS total_channel_spend FROM `maplemonk.buildskill_wh_MARKETING_CONSOLIDATED` GROUP BY 1,2 ), amazon_channel_spend AS ( SELECT LOWER(\'amazon\') AS channel, DATE(date) AS date, SUM(CAST(spend AS FLOAT64)) AS total_channel_spend FROM `maplemonk.Buildskill_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED` GROUP BY 1,2 ), vendor_sales AS ( SELECT TRIM(asin) AS asin, DATE(sales_date) AS sales_date, SUM(IFNULL(Ordered_Revenue,0)) AS sales, SUM(IFNULL(ordered_units,0)) AS total_quantity FROM `maplemonk.Buildskill_S3_Amazon_Daily_Sales_Report_Final` GROUP BY 1,2 ), amazon_ads AS ( SELECT COALESCE(CASE WHEN LENGTH(TRIM(am.asin)) = 10 THEN TRIM(am.asin) END, CASE WHEN LENGTH(TRIM(SPLIT(am.campaignname,\'-\')[SAFE_OFFSET(2)])) = 10 THEN TRIM(SPLIT(am.campaignname,\'-\')[SAFE_OFFSET(2)]) END) AS asin, DATE(am.date) AS date, SUM(IFNULL(clicks,0)) AS clicks, SUM(IFNULL(spend,0)) AS spend, SUM(IFNULL(impressions,0)) AS impressions, SUM(IFNULL(am.ATTRIBUTED_CONVERSIONS_14D,0)) AS conversions, SUM(IFNULL(am.ATTRIBUTED_SALES_14D,0)) AS conversion_value FROM `maplemonk.Buildskill_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED` am WHERE COALESCE(CASE WHEN LENGTH(TRIM(am.asin)) = 10 THEN TRIM(am.asin) END, CASE WHEN LENGTH(TRIM(SPLIT(am.campaignname,\'-\')[SAFE_OFFSET(2)])) = 10 THEN TRIM(SPLIT(am.campaignname,\'-\')[SAFE_OFFSET(2)]) END) IS NOT NULL GROUP BY 1,2 ), amazon AS ( SELECT CAST(COALESCE(vs.asin, aa.asin) AS STRING) AS PRODUCT_ID, CAST(NULL AS STRING) AS VARIANT_ID, COALESCE(vs.sales_date, aa.date) AS DATE, FORMAT_DATE(\'%A\', COALESCE(vs.sales_date, aa.date)) AS DAY_OF_WEEK, EXTRACT(YEAR FROM COALESCE(vs.sales_date, aa.date)) AS YEAR, EXTRACT(MONTH FROM COALESCE(vs.sales_date, aa.date)) AS MONTH, \'Amazon\' AS CHANNEL, CAST(NULL AS STRING) AS ACCOUNT, IFNULL(aa.clicks,0) AS CLICKS, IFNULL(aa.spend,0) AS SPEND, IFNULL(aa.impressions,0) AS IMPRESSIONS, IFNULL(aa.conversions,0) AS CONVERSIONS, IFNULL(aa.conversion_value,0) AS CONVERSION_VALUE, IFNULL(vs.sales,0) AS SALES, IFNULL(vs.total_quantity,0) AS TOTAL_QUANTITY, UPPER(TRIM(sm.master_sku)) AS SKU, UPPER(TRIM(sm.PRODUCT_TITLE)) AS product_name, CONCAT(UPPER(TRIM(sm.CATEGORY)), \' \', UPPER(TRIM(sm.SUB_CATEGORY))) AS master_category FROM vendor_sales vs FULL OUTER JOIN amazon_ads aa ON TRIM(vs.asin) = TRIM(aa.asin) AND date(vs.sales_date) = date(aa.date) LEFT JOIN sku_map sm ON TRIM(LOWER(COALESCE(vs.asin, aa.asin))) = TRIM(LOWER(sm.ASIN)) ), category_monthly_sales AS ( SELECT master_category, DATE_TRUNC(date, MONTH) AS sales_month, SUM(IFNULL(sales,0)) AS monthly_sales FROM amazon GROUP BY 1,2 ), category_past_benchmark AS ( SELECT master_category, sales_month, MAX(monthly_sales) OVER (PARTITION BY master_category ORDER BY sales_month ROWS BETWEEN 12 PRECEDING AND CURRENT ROW) AS category_benchmark FROM category_monthly_sales ) SELECT m.*, mcm.owner AS owner, IFNULL(SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL), 0) AS total_product_lvl_spend, IFNULL(CASE WHEN LOWER(m.channel) LIKE \'%amazon%\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END, 0) AS total_channel_spend, IFNULL(CASE WHEN LOWER(m.channel) LIKE \'%amazon%\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END, 0) - IFNULL(SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL), 0) AS spend_diff, CASE WHEN (CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) > SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL) AND SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL) > 0 THEN ((CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) - SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL)) * (m.conversion_value / SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL)) ELSE 0 END AS allocated_spend_diff, CASE WHEN (CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) > SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL) AND SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL) > 0 THEN m.SPEND + (((CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) - SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL)) * (m.conversion_value / SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL))) ELSE m.SPEND END AS corrected_spend, cpb.category_benchmark AS past_benchmark, IFNULL(CAST(REPLACE(st.target, \',\', \'\') AS FLOAT64),0) AS monthly_target, CAST(REPLACE(att.ASIN_level_Ads_Spends, \'%\', \'\') AS FLOAT64) as ntacos_target FROM amazon m LEFT JOIN marketing_consolidated mc ON LOWER(TRIM(CAST(m.channel AS STRING))) = LOWER(TRIM(CAST(mc.channel AS STRING))) AND CAST(m.date AS DATE) = CAST(mc.date AS DATE) LEFT JOIN amazon_channel_spend ac ON LOWER(TRIM(CAST(m.channel AS STRING))) = LOWER(TRIM(CAST(ac.channel AS STRING))) AND CAST(m.date AS DATE) = CAST(ac.date AS DATE) LEFT JOIN category_past_benchmark cpb ON m.master_category = cpb.master_category AND DATE_TRUNC(m.DATE, MONTH) = cpb.sales_month LEFT JOIN `maplemonk.Buildskill_GS_SKU_Target` st ON UPPER(TRIM(m.sku)) = UPPER(TRIM(st.sku)) AND UPPER(TRIM(st.month)) = UPPER(FORMAT_DATE(\'%B\', m.date)) LEFT JOIN `maplemonk.Buildskill_GS_Master_Category_Mapping` mcm ON REGEXP_REPLACE(UPPER(TRIM(m.master_category)), r\'\s+\', \'\') = REGEXP_REPLACE(UPPER(TRIM(mcm.master_category)), r\'\s+\', \'\') left join `maplemonk.Buildskill_GS_Amazon_Tacos_Target` att on trim(m.PRODUCT_ID) = trim(att.asin) and UPPER(TRIM(m.master_category)) = UPPER(TRIM(att.PL)) ; CREATE OR REPLACE TABLE MAPLEMONK.BUILDSKILL_CATEGORY_DAILY_SUMMARY AS SELECT DATE, DATE_TRUNC(DATE, MONTH) AS month_start, FORMAT_DATE(\'%b %d\', date) as Day, master_category, product_id, product_name, owner, SUM(IFNULL(sales,0)) AS daily_sales, SUM(IFNULL(corrected_spend,0)) AS daily_spend, SUM(IFNULL(conversion_value,0)) AS daily_paid_sales, MAX(IFNULL(past_benchmark,0)) AS past_benchmark, MAX(IFNULL(monthly_target,0)) AS monthly_target, SUM(IFNULL(conversions,0)) AS daily_ad_orders, SUM(IFNULL(total_quantity,0)) AS total_quantity, SUM(IFNULL(IMPRESSIONS,0)) AS daily_impressions, SUM(IFNULL(clicks,0)) AS daily_clicks, SAFE_DIVIDE(SUM(IFNULL(clicks,0)), SUM(IFNULL(impressions,0))) AS daily_ctr, SAFE_DIVIDE(SUM(IFNULL(conversions,0)), SUM(IFNULL(clicks,0))) AS daily_cvr, SAFE_DIVIDE(SUM(IFNULL(sales,0) * IFNULL(ntacos_target,0)), SUM(IFNULL(sales,0))) AS daily_ntacos_target, safe_divide(sum(ifnull(corrected_spend,0)), sum(ifnull(CONVERSION_VALUE,0))) as daily_acos, MAX(IFNULL(inv.Amazon_IN_Inventory,0)) AS Daily_Inventory FROM MAPLEMONK.BUILDSKILL_DB_PRODUCT_MARKETING_CONSOLIDATED a LEFT JOIN (select asin, data_fetch_date, Amazon_IN_Inventory from maplemonk.Buildskill_INVENTORY_FACT_ITEMS_amazon_vc) inv ON TRIM(UPPER(inv.asin)) = TRIM(UPPER(a.product_id)) AND inv.DATA_FETCH_DATE = a.DATE GROUP BY 1,2,3,4,5,6,7; CREATE OR REPLACE TABLE MAPLEMONK.BUILDSKILL_CATEGORY_MONTHLY_SUMMARY AS SELECT owner, month_start, master_category, product_id, product_name, MAX(past_benchmark) AS past_benchmark, MAX(IFNULL(monthly_target,0)) AS monthly_target, SUM(daily_sales) AS total_sales, SUM(daily_spend) AS total_spend, SUM(daily_paid_sales) AS paid_sales, SAFE_DIVIDE(SUM(daily_spend), SUM(daily_sales)) AS tacos, SAFE_DIVIDE(SUM(daily_spend), SUM(daily_paid_sales)) AS acos, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_sales ELSE 0 END) AS w1_nmv, CASE WHEN month_start = DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY), MONTH) AND EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) <= 7 THEN SAFE_DIVIDE(SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_sales ELSE 0 END), EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY))) * 7 ELSE SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_sales ELSE 0 END) END AS w1_trending, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_spend ELSE 0 END) AS w1_spend, CASE WHEN month_start = DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY), MONTH) AND EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) <= 7 THEN SAFE_DIVIDE(SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_spend ELSE 0 END), EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY))) * 7 ELSE SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_spend ELSE 0 END) END AS w1_trending_spend, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_paid_sales ELSE 0 END) AS w1_paid_sales, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN total_quantity ELSE 0 END) AS w1_total_quantity, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_sales ELSE 0 END) AS w2_nmv, CASE WHEN month_start = DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY), MONTH) AND EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) BETWEEN 8 AND 14 THEN SAFE_DIVIDE(SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_sales ELSE 0 END), EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) - 7) * 7 ELSE SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_sales ELSE 0 END) END AS w2_trending, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_spend ELSE 0 END) AS w2_spend, CASE WHEN month_start = DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY), MONTH) AND EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) BETWEEN 8 AND 14 THEN SAFE_DIVIDE(SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_spend ELSE 0 END), EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) - 7) * 7 ELSE SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_spend ELSE 0 END) END AS w2_trending_spend, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_paid_sales ELSE 0 END) AS w2_paid_sales, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN total_quantity ELSE 0 END) AS w2_total_quantity, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_sales ELSE 0 END) AS w3_nmv, CASE WHEN month_start = DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY), MONTH) AND EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) BETWEEN 15 AND 21 THEN SAFE_DIVIDE(SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_sales ELSE 0 END), EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) - 14) * 7 ELSE SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_sales ELSE 0 END) END AS w3_trending, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_spend ELSE 0 END) AS w3_spend, CASE WHEN month_start = DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY), MONTH) AND EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) BETWEEN 15 AND 21 THEN SAFE_DIVIDE(SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_spend ELSE 0 END), EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) - 14) * 7 ELSE SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_spend ELSE 0 END) END AS w3_trending_spend, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_paid_sales ELSE 0 END) AS w3_paid_sales, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN total_quantity ELSE 0 END) AS w3_total_quantity, SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_sales ELSE 0 END) AS w4_nmv, CASE WHEN month_start = DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY), MONTH) AND EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) >= 22 THEN SAFE_DIVIDE(SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_sales ELSE 0 END), EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) - 21) * 7 ELSE SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_sales ELSE 0 END) END AS w4_trending, SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_spend ELSE 0 END) AS w4_spend, CASE WHEN month_start = DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY), MONTH) AND EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) >= 22 THEN SAFE_DIVIDE(SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_spend ELSE 0 END), EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) - 21) * 7 ELSE SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_spend ELSE 0 END) END AS w4_trending_spend, SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_paid_sales ELSE 0 END) AS w4_paid_sales, SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN total_quantity ELSE 0 END) AS w4_total_quantity, count(distinct CASE WHEN EXTRACT(DAY FROM DATE) >= 22 then date end) as w4_days, SUM(daily_ad_orders) AS ad_orders, SUM(total_quantity) AS total_orders, SUM(daily_clicks) AS clicks, SUM(daily_impressions) AS impressions, SAFE_DIVIDE(SUM(daily_ntacos_target * daily_sales), SUM(daily_sales)) AS ntacos_target, ARRAY_AGG(Daily_Inventory ORDER BY DATE DESC LIMIT 1)[OFFSET(0)] AS Inventory FROM maplemonk.BUILDSKILL_CATEGORY_DAILY_SUMMARY GROUP BY 1,2,3,4,5; CREATE OR REPLACE TABLE MAPLEMONK.BUILDSKILL_WEEKLY_SUMMARY AS SELECT owner, month_start, FORMAT_DATE(\'%B %Y\', month_start) AS month_year, master_category, product_id, product_name, \'W1\' AS week_label, w1_nmv AS nmv, w1_spend AS spend, SAFE_DIVIDE(w1_spend, w1_nmv) AS tacos, CASE WHEN EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) <= 7 THEN SAFE_DIVIDE(w1_total_quantity, EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY))) ELSE SAFE_DIVIDE(w1_total_quantity, 7) END AS drr FROM MAPLEMONK.BUILDSKILL_CATEGORY_MONTHLY_SUMMARY UNION ALL SELECT owner, month_start, FORMAT_DATE(\'%B %Y\', month_start) AS month_year, master_category, product_id, product_name, \'W2\' AS week_label, w2_nmv AS nmv, w2_spend AS spend, SAFE_DIVIDE(w2_spend, w2_nmv) AS tacos, CASE WHEN EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) BETWEEN 8 AND 14 THEN SAFE_DIVIDE( w2_total_quantity, EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) - 7 ) ELSE SAFE_DIVIDE(w2_total_quantity, 7) END AS drr FROM MAPLEMONK.BUILDSKILL_CATEGORY_MONTHLY_SUMMARY UNION ALL SELECT owner, month_start, FORMAT_DATE(\'%B %Y\', month_start) AS month_year, master_category, product_id, product_name, \'W3\' AS week_label, w3_nmv AS nmv, w3_spend AS spend, SAFE_DIVIDE(w3_spend, w3_nmv) AS tacos, CASE WHEN EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) BETWEEN 15 AND 21 THEN SAFE_DIVIDE( w3_total_quantity, EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) - 14 ) ELSE SAFE_DIVIDE(w3_total_quantity, 7) END AS drr FROM MAPLEMONK.BUILDSKILL_CATEGORY_MONTHLY_SUMMARY UNION ALL SELECT owner, month_start, FORMAT_DATE(\'%B %Y\', month_start) AS month_year, master_category, product_id, product_name, \'W4\' AS week_label, w4_nmv AS nmv, w4_spend AS spend, SAFE_DIVIDE(w4_spend, w4_nmv) AS tacos, CASE WHEN EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) >= 22 THEN SAFE_DIVIDE( w4_total_quantity, EXTRACT(DAY FROM DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY)) - 21 ) ELSE SAFE_DIVIDE(w4_total_quantity, w4_days) END AS drr FROM MAPLEMONK.BUILDSKILL_CATEGORY_MONTHLY_SUMMARY; CREATE OR REPLACE TABLE MAPLEMONK.BUILDSKILL_AVC_DATA_AVAILABILITY AS select distinct date(sales_date) as date from maplemonk.Buildskill_S3_Amazon_Daily_Sales_Report_Final ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
